INSERT INTO project_config(project_id,key,value) VALUES ('p21','management_biographies', $bio${"version": 1, "profiles": [{"id": "masa", "name": "山地 正洋", "reading": "やまじ まさひろ", "title": "株式会社チームアルマダ 代表取締役／博士（工学）", "summary": ["慶應義塾大学大学院理工学研究科で博士（工学）を取得後、NIMS、産総研、ニューガラスフォーラム、京都大学大学院で研究に従事。2012年に京都大学発の素材ベンチャーであるティエムファクトリ株式会社を設立し、代表取締役として9年間経営した。", "現在は株式会社チームアルマダ代表取締役として、研究機関発の技術シーズを事業化するディープテック特化型スタートアップスタジオを運営している。スタートアップ設立・経営への関与、資金調達、大学・研究機関との連携、研究成果の社会実装支援を行い、事業化支援の判断・進捗・成果を蓄積して再現性を高める仕組みの構築にも取り組んでいる。"], "positions": ["株式会社チームアルマダ 代表取締役", "翔エンジニアリング株式会社 顧問", "LiSTie株式会社 社外取締役", "株式会社チャレナジー 取締役", "愛媛大学 イノベーションマネージャー", "工学院大学 イノベーション推進コーディネーター", "香川大学 客員研究員"], "career": [{"date": "1995/3", "text": "茨城県立土浦第一高等学校 卒業"}, {"date": "1999/4", "text": "慶應義塾大学 理工学部 卒業"}, {"date": "2001/3", "text": "慶應義塾大学大学院 理工学研究科 前期博士課程修了"}, {"date": "2004/3", "text": "慶應義塾大学大学院 理工学研究科 総合デザイン工学専攻 後期博士課程修了（工学博士号取得）"}, {"date": "2004/4", "text": "慶應義塾大学大学院 特任研究員"}, {"date": "2004/10", "text": "物質・材料研究機構（NIMS） ポストドクター"}, {"date": "2006/1", "text": "産業技術総合研究所（産総研） ポストドクター"}, {"date": "2009/4", "text": "一般社団法人ニューガラスフォーラム ポストドクター"}, {"date": "2011/4", "text": "京都大学大学院 社会人研究員"}, {"date": "2012/11", "text": "ティエムファクトリ株式会社 設立、代表取締役就任"}, {"date": "2021/12", "text": "ティエムファクトリ株式会社 代表取締役退任"}, {"date": "2022/7", "text": "株式会社OPTMASS COO就任（2023年4月まで）"}, {"date": "2023/1", "text": "株式会社チームアルマダ 代表取締役就任（現職）"}, {"date": "2023/3", "text": "株式会社r3kt CSO就任（2024年5月まで）"}, {"date": "2023/5", "text": "株式会社輝翠テック COO就任（2023年10月まで）"}, {"date": "2023/5", "text": "株式会社マテリアル・コンセプト CSO就任（2024年4月まで）"}, {"date": "2023/5", "text": "CrestecBio株式会社 COO就任（2024年5月まで）"}, {"date": "2023/7", "text": "LiSTie株式会社 COO就任（2025年7月まで）"}, {"date": "2023/8", "text": "株式会社JOYCLE CSO就任（2026年3月まで）"}, {"date": "2023/12", "text": "翔エンジニアリング株式会社 顧問就任（現職）"}, {"date": "2025/1", "text": "株式会社ORLIB CSO就任（2025年12月まで）"}, {"date": "2025/4", "text": "株式会社Blue Water Energy 代表取締役就任（2025年9月まで）"}, {"date": "2025/5", "text": "Yellow Duck株式会社 CSO就任（2025年8月まで）"}, {"date": "2025/7", "text": "LiSTie株式会社 COO退任、社外取締役就任（現職）"}, {"date": "2025/9", "text": "株式会社Blue Water Energy 代表取締役退任"}, {"date": "2026/1", "text": "愛媛大学 イノベーションマネージャー就任（現職）"}, {"date": "2026/4", "text": "株式会社チャレナジー 取締役就任（現職）"}, {"date": "2026/5", "text": "工学院大学 イノベーション推進コーディネーター就任（現職）"}, {"date": "2026/7", "text": "香川大学 客員研究員就任（現職）"}], "awards": ["2008 国際会議 Micro Optics Conference 最優秀論文賞", "2017 大学発ベンチャー表彰 経済産業大臣賞", "2017 新科学推進協会 グリーンサステナブルケミストリー賞", "2019 ILS（イノベーションリーダーズサミット）グランプリ", "2019 三菱UFJ Rise Up Festa 優秀賞", "2019 めぶきビジネスアワード 最優秀賞", "2021 TCIビジネスコンテスト 優秀賞", "2021 慶應義塾大学 矢上賞"]}], "sourceRef": "山地正洋略歴.docx・公式書類用プロフィール正本（2026-07-06更新）"}$bio$) ON CONFLICT(project_id,key) DO NOTHING;
